const t = Date.now();
const doc = n => `PRUEBA82-${t}-${n}`;
return [
  { json: { caso: '1 CUIT válido (sin guiones)', esperado: 'proveedor_id = PRV-001', modo: 'proveedor', cuit: '30574897099', documento_id: doc(1), origen: 'facturas' } },
  { json: { caso: '2 CUIT inexistente', esperado: 'a la cola', modo: 'proveedor', cuit: '30-99999999-1', documento_id: doc(2), origen: 'facturas' } },
  { json: { caso: '3 DNI válido', esperado: 'cliente_id = CLI-00006', modo: 'cliente', dni: '29402417', documento_id: doc(3), origen: 'reclamos' } },
  { json: { caso: '4 DNI repetido en dos clientes', esperado: 'a la cola (2 coincidencias)', modo: 'cliente', dni: '45645285', documento_id: doc(4), origen: 'reclamos' } },
  { json: { caso: '5 texto con datos personales', esperado: 'sin correo, teléfono ni dirección; 3 marcadores', modo: 'texto', documento_id: doc(5), origen: 'reclamos',
            texto: 'Me llegó el pedido de ladrillos huecos con varias piezas rotas. Les mando fotos. La dirección de entrega es Lavalle 1920, Haedo. Pueden escribirme a <CORREO>. Mi teléfono es 11-3850-1749.' } },
  { json: { caso: '6 texto sin datos personales', esperado: 'texto igual, 0 marcadores', modo: 'texto', documento_id: doc(6), origen: 'reclamos',
            texto: 'El pedido P-1234 llegó con el remito equivocado.' } },
];

const casos = $('CA82P_Casos').all().map(i => i.json);
const res = $input.all().map(i => i.json);
const ok = [
  r => r.resuelto === true && r.proveedor_id === 'PRV-001',
  r => r.resuelto === false && r.derivado_a_cola === true,
  r => r.resuelto === true && r.cliente_id === 'CLI-00006',
  r => r.resuelto === false && /2 coincidencias/.test(r.motivo || ''),
  r => r.resuelto === true && r.cantidad_marcadores === 3 && !/@|11-3850-1749|Lavalle 1920/.test(r.texto_enmascarado || '@'),
  r => r.resuelto === true && r.cantidad_marcadores === 0 && r.texto_enmascarado === casos[5].texto,
];
return casos.map((c, i) => {
  const r = res[i] || {};
  return { json: { caso: c.caso, esperado: c.esperado, resultado: ok[i](r) ? 'PASA' : 'FALLA', detalle: JSON.stringify(r).slice(0, 400) } };
});
